import '../../features/intelligence/domain/intelligence_library.dart';

/// Русский справочник цифровых индикаторов; логика и категории не меняются.
class RussianIntelligenceContent {
  RussianIntelligenceContent._();
  static const Map<String, Map<String,String>> _data = {
    'url-http': {'title':'Незашифрованное HTTP-соединение','signal':'Адрес сайта начинается с http://, а не с https://.','meaning':'Соединение не использует TLS для защиты данных при передаче. Информация может быть раскрыта или изменена в сети.','action':'Не вводите пароли и платёжные данные. Перейдите на сайт организации через надёжную закладку или независимо проверенный адрес.','limit':'HTTPS защищает соединение, но не доказывает подлинность самого сайта.'},
    'url-userinfo': {'title':'Вводящая в заблуждение информация в URL','signal':'В URL есть текст перед символом @, например https://trusted.example@unknown.example/.','meaning':'Браузер считает именем узла текст после символа @. Выглядящий надёжным текст перед ним может отвлекать внимание.','action':'Проверьте фактическое имя узла сразу после @ и регистрируемый домен до перехода.','limit':'Данные пользователя в URL необычны, но сами по себе не доказывают злой умысел.'},
    'url-punycode': {'title':'Интернационализированный домен / Punycode','signal':'Имя узла содержит метку xn-- или визуально похожие символы.','meaning':'Интернационализированные домены могут использовать символы разных письменностей, похожие на латинские буквы.','action':'Проверьте точное написание и владельца домена по надёжному источнику. Не полагайтесь только на знакомый логотип или отображаемое имя.','limit':'Многие законные сайты используют интернационализированные домены.'},
    'url-subdomains': {'title':'Цепочка вложенных поддоменов','signal':'Имя узла содержит много уровней, например login.account.example.invalid.','meaning':'Регистрируемый домен не обязательно является первым знакомым словом в адресе. Злоумышленник может разместить название бренда в контролируемом им поддомене.','action':'Читайте имя узла справа налево, определите регистрируемый домен и проверьте его независимо.','limit':'Длинные цепочки поддоменов также используются в законных целях.'},
    'message-urgency': {'title':'Срочность и давление','signal':'Сообщение требует немедленных действий, угрожает закрытием аккаунта или устанавливает искусственный срок.','meaning':'Давление мешает независимой проверке и подталкивает получателя действовать необдуманно.','action':'Сделайте паузу. Свяжитесь с организацией через известное официальное приложение, сайт или номер, а не по контактам из сообщения.','limit':'Срочные формулировки встречаются и в законных сообщениях; важен контекст.'},
    'message-credentials': {'title':'Запрос пароля или одноразового кода','signal':'Отправитель просит пароль, OTP, код восстановления или подтверждение неожиданного входа.','meaning':'Такие секреты и подтверждения могут дать доступ к аккаунту или разрешить транзакцию.','action':'Никогда не раскрывайте пароли и OTP. Отклоняйте неожиданные запросы подтверждения и обращайтесь в сервис по официальному каналу.','limit':'Совпадение ключевых слов указывает только на тему, но не устанавливает личность или намерения отправителя.'},
    'message-payment': {'title':'Неожиданный платёж или возврат','signal':'Сообщение требует перевода, комиссии за обработку, оформления возврата или оплаты для получения выгоды.','meaning':'Неожиданные финансовые инструкции могут использоваться для перенаправления денег или сбора платёжных данных.','action':'Перед действием независимо проверьте получателя, сумму и причину через отдельный надёжный канал.','limit':'Упоминания платежей обычны и в законных счетах и уведомлениях.'},
    'qr-payment': {'title':'Платёжный запрос через QR-код','signal':'Содержимое QR-кода использует платёжную схему, например upi://pay.','meaning':'Сканирование может подготовить платёж получателю. QR-код не подтверждает личность получателя и правильность суммы.','action':'Перед подтверждением проверьте имя получателя, UPI ID и сумму в платёжном приложении. Отмените операцию при любом несовпадении.','limit':'Платёжное содержимое само по себе не является мошенничеством; проверяйте параметры операции.'},
    'qr-action': {'title':'QR-код со ссылкой на действие','signal':'QR-код содержит веб-, телефонное, почтовое, SMS- или специфичное для приложения действие.','meaning':'При обработке другим приложением содержимое может открыть адрес или предварительно заполнить действие.','action':'Сначала изучите декодированное содержимое. Не открывайте незнакомые ссылки и не подтверждайте заполненные действия без проверки.','limit':'Тип содержимого сам по себе не подтверждает надёжность источника.'},
    'account-mfa': {'title':'Неожиданный запрос подтверждения MFA','signal':'Вы получили запрос подтверждения входа или одноразовый код, который не запрашивали.','meaning':'Кто-то может пытаться войти с вашим идентификатором и паролем; также код мог быть создан случайно.','action':'Отклоните запрос, не сообщайте код, при необходимости смените пароль через официальный сервис и проверьте активные сеансы.','limit':'Неожиданный запрос — предупреждающий сигнал, а не доказательство взлома аккаунта.'},
  };
  static IntelligenceEntry localize(IntelligenceEntry item,String code) {
    if(code!='ru') return item; final v=_data[item.id]; if(v==null)return item;
    return IntelligenceEntry(id:item.id,title:v['title']!,category:item.category,signal:v['signal']!,meaning:v['meaning']!,action:v['action']!,limit:v['limit']!);
  }
}
